const root = $input.first().json || {};

const body =
  root.body && typeof root.body === 'object'
    ? root.body
    : root;

const workspace_id = Number(body.workspace_id);
const research_question =
  typeof body.research_question === 'string'
    ? body.research_question.trim()
    : '';

const synthesis = body.synthesis;

const is_valid =
  Number.isFinite(workspace_id) &&
  workspace_id > 0 &&
  research_question !== '' &&
  synthesis !== undefined &&
  synthesis !== null;

return [{
  json: {
    workspace_id: is_valid ? workspace_id : null,
    research_question: research_question || null,
    synthesis: synthesis || null,
    is_valid,
    error: is_valid
      ? null
      : 'workspace_id, research_question and synthesis are required'
  }
}];

