You are a rigorous research analyst. You identify research gaps by reasoning ONLY from the supplied synthesis. Do NOT invent papers, evidence, citations, or facts that are not present in the supplied input. If the synthesis does not support a claim, do not make it.

Return ONLY a JSON object with exactly this structure:
{
  "gap_summary": "A concise summary of the major research gaps.",
  "research_gaps": [
    {
      "gap": "Specific research gap",
      "evidence": "What in the supplied synthesis indicates this gap",
      "importance": "Why this gap matters"
    }
  ],
  "research_opportunities": [
    "Potential research direction 1",
    "Potential research direction 2"
  ]
}

=Analyze the following research synthesis and identify the research gaps. Reason only from the supplied synthesis.

workspace_id: {{ $json.workspace_id }}

research_question:
{{ $json.research_question }}

synthesis:
{{ JSON.stringify($json.synthesis) }}

parameters.jsCode:
const upstream = $('Normalize Gap Input').first().json || {};
const workspace_id = upstream.workspace_id ?? null;
const research_question = upstream.research_question ?? null;

const aiItem = $input.first().json || {};

// With JSON output enabled, message.content is already a parsed object;
// fall back to parsing a string if needed.
let raw = aiItem.message && aiItem.message.content !== undefined
  ? aiItem.message.content
  : aiItem;

let gap_analysis = null;
let error = null;

try {
  if (typeof raw === 'string') {
    gap_analysis = JSON.parse(raw);
  } else if (raw && typeof raw === 'object') {
    gap_analysis = raw;
  }
} catch (e) {
  gap_analysis = null;
  error = 'Failed to parse AI gap analysis output: ' + e.message;
}

const is_valid =
  gap_analysis !== null &&
  typeof gap_analysis === 'object' &&
  Array.isArray(gap_analysis.research_gaps) &&
  gap_analysis.research_gaps.length > 0;

if (!is_valid && !error) {
  error = 'AI gap analysis did not contain a non-empty research_gaps array';
}

return [{
  json: {
    workspace_id,
    research_question,
    gap_analysis: is_valid ? gap_analysis : null,
    is_valid,
    error: is_valid ? null : error
  }
}];

return [{
  json: {
    success: true,
    message: 'Research gaps identified successfully',
    workspace_id: $json.workspace_id || null,
    research_question: $json.research_question || null,
    gap_analysis: $json.gap_analysis || null
  }
}];

return [{
  json: {
    success: false,
    message: 'Research gap analysis failed',
    workspace_id: $json.workspace_id || null,
    error: $json.error || 'Unknown gap analysis error'
  }
}];

return [{
  json: {
    success: false,
    error: $json.error || 'Invalid research gap discovery input',
    workspace_id: $json.workspace_id || null
  }
}];
